int set_orinoco_auth_params(struct net_device *dev, struct iw_request_info *info,
                            union iwreq_data *wrqu, char *extra)
{
    struct orinoco_private *priv = (struct orinoco_private *)dev->ml_priv;
    int ret = 0;

    /* Lock the device for exclusive access */
    mutex_lock(&priv->mutex);

    /* Handle authentication parameters based on wrqu data */
    switch (wrqu->data.flags & IW_AUTH_INDEX) {
    case IW_AUTH_KEY_MGMT:
        /* Process key management settings */
        switch (wrqu->param.value) {
        case IW_AUTH_KEY_MGMT_NONE:
            priv->key_mgmt = 0;
            break;
        case IW_AUTH_KEY_MGMT_802_1X:
            priv->key_mgmt = 1;
            break;
        case IW_AUTH_KEY_MGMT_PSK:
            priv->key_mgmt = 2;
            break;
        default:
            ret = -EINVAL;
        }
        break;
    case IW_AUTH_TKIP_COUNTERMEASURES:
        /* Enable or disable TKIP countermeasures */
        priv->tkip_countermeasures = wrqu->param.value;
        break;
    case IW_AUTH_ALGORITHM:
        /* Process authentication algorithm */
        switch (wrqu->param.value) {
        case IW_AUTH_ALG_OPEN_SYSTEM:
            priv->auth_alg = 0;
            break;
        case IW_AUTH_ALG_SHARED_KEY:
            priv->auth_alg = 1;
            break;
        case IW_AUTH_ALG_LEAP:
            priv->auth_alg = 2;
            break;
        default:
            ret = -EINVAL;
        }
        break;
    case IW_AUTH_WPA_VERSION:
        /* Handle WPA version */
        switch (wrqu->param.value) {
        case IW_AUTH_WPA_VERSION_DISABLED:
            priv->wpa_version = 0;
            break;
        case IW_AUTH_WPA_VERSION_1:
            priv->wpa_version = 1;
            break;
        case IW_AUTH_WPA_VERSION_2:
            priv->wpa_version = 2;
            break;
        default:
            ret = -EINVAL;
        }
        break;
    default:
        ret = -EOPNOTSUPP;
    }

    /* Unlock the device after processing */
    mutex_unlock(&priv->mutex);

    return ret;
}

int handle_orinoco_auth_params(struct net_device *dev, struct iw_request_info *info,
                               union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *) dev->priv;

    lock_device(dev);

    if (wrqu->data.flags & IW_AUTH_KEY_MGMT) {
        switch (wrqu->data.flags) {
        case IW_AUTH_KEY_MGMT_NONE:
            priv->key_mgmt = KEY_MGMT_NONE;
            break;
        case IW_AUTH_KEY_MGMT_802_1X:
            priv->key_mgmt = KEY_MGMT_802_1X;
            break;
        case IW_AUTH_KEY_MGMT_WPA:
            priv->key_mgmt = KEY_MGMT_WPA;
            break;
        default:
            ret = -EINVAL;
            break;
        }
    } else if (wrqu->data.flags & IW_AUTH_TKIP_COUNTERMEASURES) {
        priv->tkip_countermeasures = wrqu->data.flags & IW_AUTH_TKIP_COUNTERMEASURES;
    } else if (wrqu->data.flags & IW_AUTH_ALGORITHM) {
        switch (wrqu->data.flags & IW_AUTH_ALG_MASK) {
        case IW_AUTH_ALG_OPEN_SYSTEM:
            priv->auth_alg = AUTH_OPEN_SYSTEM;
            break;
        case IW_AUTH_ALG_SHARED_KEY:
            priv->auth_alg = AUTH_SHARED_KEY;
            break;
        case IW_AUTH_ALG_LEAP:
            priv->auth_alg = AUTH_LEAP;
            break;
        default:
            ret = -EINVAL;
            break;
        }
    } else if (wrqu->data.flags & IW_AUTH_WPA_VERSION) {
        if ((wrqu->data.flags & IW_AUTH_WPA_VERSION) == IW_AUTH_WPA_VERSION_1) {
            priv->wpa_version = WPA_VERSION_1;
        } else {
            ret = -EOPNOTSUPP;
        }
    } else {
        ret = -EOPNOTSUPP;
    }

    unlock_device(dev);
    return ret;
}

int orinoco_set_auth(struct net_device *dev, struct iw_request_info *info,
                     union iwreq_data *wrqu, char *extra)
{
    struct orinoco_private *priv = (struct orinoco_private *) dev->priv;
    int ret = 0;

    lock_kernel();
    switch (wrqu->data.flags & IW_AUTH_INDEX) {
    case IW_AUTH_KEY_MGMT:
        if (wrqu->data.length != sizeof(u16)) {
            ret = -EINVAL;
            break;
        }
        priv->auth_key_mgmt = *(u16 *) extra;
        break;
    case IW_AUTH_TKIP_COUNTERMEASURES:
        if (wrqu->data.length != sizeof(u8)) {
            ret = -EINVAL;
            break;
        }
        priv->tkip_countermeasures = *(u8 *) extra;
        break;
    case IW_AUTH_ALGORITHM:
        if (wrqu->data.length != sizeof(u16)) {
            ret = -EINVAL;
            break;
        }
        priv->auth_algorithm = *(u16 *) extra;
        break;
    case IW_AUTH_WPA_VERSION:
        if (wrqu->data.length != sizeof(u16)) {
            ret = -EINVAL;
            break;
        }
        priv->wpa_version = *(u16 *) extra;
        break;
    default:
        ret = -EOPNOTSUPP;
        break;
    }
    unlock_kernel();
    return ret;
}

int orinoco_set_auth(struct net_device *dev, struct iw_request_info *info,
                     union iwreq_data *wrqu, char *extra)
{
    struct orinoco_private *lp = (struct orinoco_private *)dev->priv;
    int err = 0;

    /* Lock the device */
    mutex_lock(&lp->mutex);

    switch (wrqu->data.flags) {
    case IW_AUTH_KEY_MGMT:
        if (wrqu->data.value >= IW_AUTH_KEY_MGMT_WPA && wrqu->data.value <= IW_AUTH_KEY_MGMT_FT_IEEE8021X)
            lp->auth_mode = wrqu->data.value;
        else
            err = -EINVAL;
        break;
    case IW_AUTH_TKIP_COUNTERMEASURES:
        if (wrqu->data.value == 1)
            lp->tkip_countermeasures = 1;
        else if (wrqu->data.value == 0)
            lp->tkip_countermeasures = 0;
        else
            err = -EINVAL;
        break;
    case IW_AUTH_ALGORITHM:
        if (wrqu->data.value == IW_AUTH_ALG_OPEN_SYSTEM ||
            wrqu->data.value == IW_AUTH_ALG_SHARED_KEY ||
            wrqu->data.value == IW_AUTH_ALG_LEAP)
            lp->auth_alg = wrqu->data.value;
        else
            err = -EINVAL;
        break;
    case IW_AUTH_WPA_VERSION:
        if (wrqu->data.value == IW_AUTH_WPA_VERSION_DISABLED ||
            wrqu->data.value == IW_AUTH_WPA_VERSION_1 ||
            wrqu->data.value == IW_AUTH_WPA_VERSION_2)
            lp->wpa_version = wrqu->data.value;
        else
            err = -EINVAL;
        break;
    default:
        err = -EOPNOTSUPP;
        break;
    }

    /* Unlock the device */
    mutex_unlock(&lp->mutex);

    return err;
}

int set_auth_parameters(struct net_device *dev, struct iw_request_info *info, union iwreq_data *wrqu, char *extra)
{
    int ret = 0;
    struct orinoco_private *priv = (struct orinoco_private *)dev->priv;

    lock_kernel();

    if (wrqu->data.flags & IW_AUTH_KEY_MGMT) {
        int key_mgmt = wrqu->data.flags & IW_AUTH_KEY_MGMT;
        if (key_mgmt != IW_AUTH_KEY_MGMT_NONE &&
            key_mgmt != IW_AUTH_KEY_MGMT_802_1X &&
            key_mgmt != IW_AUTH_KEY_MGMT_PSK)
            ret = -EINVAL;
        else
            priv->key_mgmt = key_mgmt;
    }

    if (wrqu->data.flags & IW_AUTH_TKIP_COUNTERMEASURES) {
        int tkip = wrqu->data.flags & IW_AUTH_TKIP_COUNTERMEASURES;
        priv->tkip_countermeasures = tkip;
    }

    if (wrqu->data.flags & IW_AUTH_ALGORITHM) {
        int auth_alg = wrqu->data.flags & IW_AUTH_ALGORITHM;
        if (auth_alg != IW_AUTH_ALG_OPEN_SYSTEM &&
            auth_alg != IW_AUTH_ALG_SHARED_KEY &&
            auth_alg != IW_AUTH_ALG_LEAP)
            ret = -EINVAL;
        else
            priv->auth_alg = auth_alg;
    }

    if (wrqu->data.flags & IW_AUTH_WPA_VERSION) {
        int wpa_version = wrqu->data.flags & IW_AUTH_WPA_VERSION;
        if (wpa_version != IW_AUTH_WPA_VERSION_DISABLED &&
            wpa_version != IW_AUTH_WPA_VERSION_1 &&
            wpa_version != IW_AUTH_WPA_VERSION_2)
            ret = -EINVAL;
        else
            priv->wpa_version = wpa_version;
    }

    unlock_kernel();

    return ret;
}
